function validateEmail(s){ s=(s||'').trim(); if(!s) return {valid:false, reason:'empty'};
  if(s.length>254) return {valid:false, reason:'too long'};
  if(!/^[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}$/.test(s)) return {valid:false, reason:'format'};
  return {valid:true, reason:''}; }

var EXPORTS={validateEmail:validateEmail};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.EmailValidateForgePure = EXPORTS; }
